use vstd::prelude::*;

verus! {
    // Specification for the flipud function
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        requires
            // The input vector can be of any length, including zero
            true,
        ensures
            // The output vector has the same length as the input vector
            result.len() == m.len() &&
            // For every valid index i, the element at index i of the result
            // is equal to the element at index (n - 1 - i) of the input
            forall|i: nat| 0 <= i < m.len() as nat ==> result[i] == m[(m.len() as nat - 1 - i)],
    {
        let n = m.len() as nat;
        let mut result: Vec<f32> = Vec::with_capacity(n as usize);
        
        // Fill the result vector in reverse order
        let mut idx: nat = 0;
        while idx < n
            invariant
                idx <= n,
                result.len() == idx as usize,
                forall|i: nat| 0 <= i < idx ==> result[i] == m[(n - 1 - i)],
            decreases n - idx,
        {
            // Push the element from the end of m to the result
            result.push(m[(n - 1 - idx)]);

            // Increment the index
            idx = idx + 1;
        }
        
        result
    }
}

